"use client";

import { useAppStore } from '@/lib/store';
import { useEffect, useRef, useState } from 'react';
import { Music, Volume2, VolumeX } from 'lucide-react';
import { Slider } from '@/components/ui/slider';

export function BgmPlayer() {
  const { profile } = useAppStore();
  const audioRef = useRef<HTMLAudioElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(0.5);
  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    if (audioRef.current && profile.bgmUrl) {
      // pause old one
      audioRef.current.pause();
      audioRef.current.src = profile.bgmUrl;
      audioRef.current.load();
      audioRef.current.volume = volume;
      setIsPlaying(false);
    }
  }, [profile.bgmUrl]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume]);

  if (!profile.bgmUrl) return null;

  const togglePlay = () => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
      } else {
        const playPromise = audioRef.current.play();
        if (playPromise !== undefined) {
          playPromise.catch(_error => {
            // Autoplay blocked handling here
            console.log("Audio play blocked");
          });
        }
      }
      setIsPlaying(!isPlaying);
    }
  };

  return (
    <div 
      className="fixed bottom-6 right-6 z-50 flex items-center bg-card/80 backdrop-blur shadow-lg shadow-black/10 rounded-full border border-border transition-all"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <audio ref={audioRef} loop />
      
      {/* 볼륨 슬라이더 (호버 시 표시) */}
      <div className={`overflow-hidden transition-all duration-300 ease-in-out flex items-center ${isHovered ? 'w-24 pl-4 opacity-100' : 'w-0 opacity-0'}`}>
        <Slider
          value={[volume * 100]}
          max={100}
          step={1}
          onValueChange={(vals) => setVolume(vals[0] / 100)}
          className="w-20"
        />
      </div>

      <button 
        onClick={togglePlay} 
        className="w-12 h-12 rounded-full hover:bg-primary/20 transition-colors flex items-center justify-center relative group"
        aria-label="Toggle background music"
      >
        {isPlaying ? <Volume2 className="w-5 h-5 text-primary" /> : <VolumeX className="w-5 h-5 text-muted-foreground" />}
        {isPlaying && (
          <span className="absolute -top-1 -right-1 flex h-3 w-3">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary opacity-75"></span>
            <span className="relative inline-flex rounded-full h-3 w-3 bg-primary"></span>
          </span>
        )}
      </button>
    </div>
  );
}