"use client";

import { useEffect } from 'react';
import { useAppStore } from '@/lib/store';

export function DataSyncInitializer({ children }: { children: React.ReactNode }) {
  const fetchData = useAppStore((state) => state.fetchData);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return <>{children}</>;
}
